#:sdk Microsoft.NET.Sdk.Web #:package WatchDog.NET@3.0.0 #:package System.Threading.Channels@8.0.0 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable  using System.Threading.Channels; using System.Buffers;  public class LogPipeline : BackgroundService {     private readonly Channel<ReadOnlyMemory<byte>> _channel;     private readonly IMemoryOwner<byte> _memoryOwner;          public LogPipeline()     {         _channel = Channel.CreateBounded<ReadOnlyMemory<byte>>(10000);         _memoryOwner = MemoryPool<byte>.Shared.Rent(4096);     }      protected override async Task ExecuteAsync(CancellationToken stoppingToken)     {         await foreach (var memory in _channel.Reader.ReadAllAsync(stoppingToken))         {             using var lease = _memoryOwner.Memory[..memory.Length];             memory.CopyTo(lease.Memory);             // 处理日志数据         }     } }  var builder = WebApplication.CreateBuilder(); builder.Services.AddHostedService<LogPipeline>(); builder.Services.AddWatchDogServices(); var app = builder.Build(); app.UseWatchDog(); app.Run();
